/*
 * approved -> step approved; changes -> step changes_asked.
 * Asking for changes needs a note saying what to change (DBU-06): a learner told only
 * "changes asked" cannot act on it. Approving takes an optional note.
 * The step is saved only if it is still handed_in (ifMatch), so a verdict can
 * never move a step that something else has already moved.
 */
(async () => {
  try {
    const verdicts = { approved: 'approved', changes: 'changes_asked' };
    const verdict = String(Inputs.verdict || '');
    if (!verdicts[verdict]) throw new Error('verdict must be approved or changes');
    const note = String(Inputs.note || '').trim();
    if (verdict === 'changes' && !note) throw new Error('asking for changes needs a note');
    if (note.length > 5000) throw new Error('note too long');
    const id = String(Inputs.submissionId || '');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });

    const found = id ? await q('Submission', { objectId: { equalTo: id } }) : [];
    if (found.length !== 1) throw new Error('no submission ' + id);
    const sub = found[0];
    if (sub.review !== 'pending') throw new Error('already reviewed');
    const versions = await q('Submission', { step: { equalTo: sub.step } });
    if (versions.some((v) => v.version > sub.version)) throw new Error('not the newest version');
    const steps = await q('Step', { objectId: { equalTo: sub.step } });
    if (steps.length !== 1 || steps[0].kind !== 'homework') throw new Error('no homework step for ' + id);

    const now = new Date().toISOString();
    await Noodl.Records.save(sub.objectId, { review: verdict, reviewNote: note || null, reviewedAt: now },
      { className: 'Submission', ifMatch: { review: 'pending' } });
    await Noodl.Records.save(steps[0].objectId, { status: verdicts[verdict] },
      { className: 'Step', ifMatch: { status: 'handed_in' } });
    await Noodl.Records.create('Doorbell', { learner: sub.learner, topic: 'submission' },
      { acl: { [sub.learner]: { read: true }, 'role:staff': { read: true } } });

    Outputs.review = verdict;
    Outputs.stepStatus = verdicts[verdict];
    Outputs.reviewedAt = now;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:reviewSubmission]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
